    "id", "empNumber", "reasonId", "date",
    "termination_time", "terminationTimeZoneName",
    "termination_performed_user_id", "termination_job_record_history_id",
    "reactivationDate", "reactivation_time", "reactivationTimeZoneName",
    "reactivation_performed_user_id", "reactivation_job_record_history_id",
    "reactivated", "update_joined_date", "reactivation_failed",
    "note", "flaged", "terminateinfuture"
];

pm.test("Termination is saved", function () {
    pm.response.to.have.status(200);   // change to 201 if that is what the API returns
});

const body = pm.response.json();
const data = body.data || {};

pm.test("Success message is returned", function () {
    pm.expect(body.messages && body.messages.success).to.eql("Successfully Saved");
});

pm.test("Response matches the termination schema", function () {
    const raw = pm.collectionVariables.get("terminateEmployeeSchema");
    pm.expect(raw, "terminateEmployeeSchema fixture is missing").to.be.a("string").and.not.empty;
    pm.response.to.have.jsonSchema(JSON.parse(raw));
});

pm.test("All expected termination properties are present", function () {
    dataProperties.forEach(p => pm.expect(data).to.have.property(p));
});

pm.test("Termination record has an id", function () {
    pm.expect(data.id, "termination record id").to.exist;
});

pm.test("Termination is recorded against the correct employee", function () {
    pm.expect(String(data.empNumber)).to.eql(String(pm.variables.get("expectedEmpNumber")));
});

pm.test("Termination details match what was sent", function () {
    pm.expect(data.date).to.eql(pm.variables.get("terminationDate"));
    pm.expect(data.note).to.eql(pm.variables.get("terminationNote"));
    pm.expect(Number(data.reasonId)).to.eql(Number(pm.variables.get("terminationReason")));
    pm.expect(data.termination_time).to.include(pm.variables.get("time"));
    pm.expect(data.terminationTimeZoneName).to.include(pm.variables.get("timezone"));
});

pm.test(`terminateinfuture is correct for the '${SCENARIO}' scenario`, function () {
    pm.expect(data.terminateinfuture).to.eql(pm.variables.get("expectFutureFlag"));
});

const SCENARIO = "future"; 
const fx = JSON.parse(pm.collectionVariables.get("terminationFixtures") || "{}")[SCENARIO];
if (!fx) throw new Error(`No fixture defined for scenario '${SCENARIO}'`);

let list = [];
try {
    const parsed = JSON.parse(pm.collectionVariables.get("terminateEmployeesList") || "[]");
    list = Array.isArray(parsed) ? parsed : [];
} catch (e) {
    list = [];
}

const selected = list.find(e => e.tag === SCENARIO);

if (!selected) {
    throw new Error(
        `Precondition failed: no employee created for scenario '${SCENARIO}'. ` +
        `Tags available: ${list.map(e => e.tag).join(", ") || "none"}`
    );
}

const termination = new Date();
termination.setDate(termination.getDate() + 30 + fx.terminationOffsetDays);

pm.variables.set("scenarioTag",       SCENARIO);
pm.variables.set("emp_number",        selected.empNumber);
pm.variables.set("expectedEmpNumber", selected.empNumber);
pm.variables.set("terminationDate",   termination.toISOString().split("T")[0]);
pm.variables.set("terminationNote",   fx.note);
pm.variables.set("terminationReason", fx.reasonId);
pm.variables.set("time",              fx.time);
pm.variables.set("timezone",          fx.timezone);
pm.variables.set("expectFutureFlag",  fx.expectFutureFlag);
pm.variables.set("flagValue",         0);

